%script

-- Find the importance of attributes that independently impact the target attribute:  LIFETIME_VALUE_CATEGORY

DECLARE
    v_sql varchar2(100);

BEGIN

-- Drop build settings
BEGIN
    v_sql := 'DROP TABLE ATT_IMPORT_MODE_SETTINGS PURGE';
    EXECUTE IMMEDIATE v_sql;
    DBMS_OUTPUT.PUT_LINE (v_sql ||': succeeded');
EXCEPTION
    WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE (v_sql ||': drop unneccessary - no table exists');
END;

-- Drop model
BEGIN
    v_sql := 'CALL DBMS_DATA_MINING.DROP_MODEL(''AI_EXPLAIN_OUTPUT_TOP_CUSTOMERS'')';
    EXECUTE IMMEDIATE v_sql;
    DBMS_OUTPUT.PUT_LINE (v_sql ||': succeeded');
EXCEPTION
    WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE (v_sql ||': drop unneccessary - no model exists');
END;

BEGIN
    EXECUTE IMMEDIATE 'CREATE TABLE ATT_IMPORT_MODE_SETTINGS (SETTING_NAME VARCHAR2(30),SETTING_VALUE VARCHAR2(4000))';
    EXECUTE IMMEDIATE 'INSERT INTO ATT_IMPORT_MODE_SETTINGS (SETTING_NAME, SETTING_VALUE) VALUES (''ALGO_NAME'', ''ALGO_AI_MDL'')';
    EXECUTE IMMEDIATE 'INSERT INTO ATT_IMPORT_MODE_SETTINGS (SETTING_NAME, SETTING_VALUE) VALUES (''PREP_AUTO'', ''ON'')';
    DBMS_OUTPUT.PUT_LINE ('CREATED MODEL BUILD SETTINGS TABLE: ATT_IMPORT_MODE_SETTINGS ');
END;


BEGIN
    DBMS_DATA_MINING.CREATE_MODEL(
        MODEL_NAME               => 'AI_EXPLAIN_OUTPUT_TOP_CUSTOMERS',
        MINING_FUNCTION          => DBMS_DATA_MINING.ATTRIBUTE_IMPORTANCE,
        DATA_TABLE_NAME          => 'PREDICT_LTV_BIN',
        CASE_ID_COLUMN_NAME      => 'CUSTOMER_ID',
        TARGET_COLUMN_NAME       => 'LIFETIME_VALUE_CATEGORY',
        SETTINGS_TABLE_NAME      => 'ATT_IMPORT_MODE_SETTINGS');
