%script

-- Consolidate all algorithms's lift data into one table.

DECLARE
v_sql varchar2(100);

BEGIN

BEGIN
v_sql := 'DROP TABLE all_lift_data PURGE';
EXECUTE IMMEDIATE v_sql;
DBMS_OUTPUT.PUT_LINE (v_sql ||': succeeded');
EXCEPTION
WHEN OTHERS THEN
DBMS_OUTPUT.PUT_LINE (v_sql ||': drop unneccessary - no table exists');
END;

EXECUTE IMMEDIATE 'CREATE TABLE all_lift_data (algo_name VARCHAR2(50), QUANTILE_NUMBER NUMBER, GAIN_CUMULATIVE NUMBER)';
DBMS_OUTPUT.PUT_LINE ('Merge model lift tables');

COMMIT;
END;

%script
BEGIN
BEGIN
    EXECUTE IMMEDIATE 'insert into all_lift_data (QUANTILE_NUMBER, GAIN_CUMULATIVE, algo_name) select QUANTILE_NUMBER, GAIN_CUMULATIVE, cast(''ALGO_DECISION_TREE'' as VARCHAR(50)) AS ALGO_NAME from N1_LIFT_TABLE_DT';
    COMMIT;
    EXECUTE IMMEDIATE 'insert into all_lift_data (QUANTILE_NUMBER, GAIN_CUMULATIVE, algo_name) select QUANTILE_NUMBER, GAIN_CUMULATIVE, cast(''ALGO_SUPPORT_VECTOR_MACHINES'' as VARCHAR(50)) AS ALGO_NAME from N1_LIFT_TABLE_SVM';
    COMMIT;
    EXECUTE IMMEDIATE 'insert into all_lift_data (QUANTILE_NUMBER, GAIN_CUMULATIVE, algo_name) select QUANTILE_NUMBER, GAIN_CUMULATIVE, cast(''ALGO_RANDOM_FOREST'' as VARCHAR(50)) AS ALGO_NAME from N1_LIFT_TABLE_RF';
    COMMIT;
    EXECUTE IMMEDIATE 'insert into all_lift_data (QUANTILE_NUMBER, GAIN_CUMULATIVE, algo_name) select QUANTILE_NUMBER, GAIN_CUMULATIVE, cast(''ALGO_NEURAL_NETWORK'' as VARCHAR(50)) AS ALGO_NAME from N1_LIFT_TABLE_NN';
    COMMIT;
    EXECUTE IMMEDIATE 'insert into all_lift_data (QUANTILE_NUMBER, GAIN_CUMULATIVE, algo_name) select QUANTILE_NUMBER, GAIN_CUMULATIVE, cast(''ALGO_NAIVE_BAYES'' as VARCHAR(50)) AS ALGO_NAME from N1_LIFT_TABLE_NB';
    COMMIT;
    DBMS_OUTPUT.PUT_LINE ('Merge model lift tables');
END;

END;
/

