%sql

-- For the predicted High Value Customers, see the distribution of Facebook Influence Score

SELECT * FROM predict_ltv_bin WHERE CUSTOMER_ID IN (SELECT CUSTOMER_ID FROM ltv_bin_apply_data_v_rf WHERE PROBABILITY IN  (SELECT MAX(PROBABILITY) FROM ltv_bin_apply_data_v_rf GROUP BY CUSTOMER_ID) AND PREDICTION='High');

%script

-- For simplicity, we copy the original dataset and give it a new name 


BEGIN
EXECUTE IMMEDIATE 'DROP TABLE CREDIT_SCORING_100K_TOP';
EXCEPTION WHEN OTHERS THEN NULL;
EXECUTE IMMEDIATE 'CREATE TABLE CREDIT_SCORING_100K_TOP AS (SELECT * FROM CREDIT_SCORING_100K_LTV)';
EXECUTE IMMEDIATE 'COMMIT';

END;

%script

-- Run Random Forest on New Customer Data

BEGIN EXECUTE IMMEDIATE 'DROP VIEW credit_scoring_100k_apply_data_v_rf';
EXCEPTION WHEN OTHERS THEN NULL; END;
/
CREATE VIEW credit_scoring_100k_apply_data_v_rf
AS 
SELECT 
"CUSTOMER_ID", t.* FROM credit_scoring_100k_top s, TABLE(PREDICTION_SET(RF_MLS_LTV_BIN USING *)) t;

%sql

-- Show the results after the running Random Forest on new Customer data

SELECT * FROM credit_scoring_100k_apply_data_v_rf;

%sql

-- Assign Prediction based on highest likelihood

SELECT CUSTOMER_ID, PREDICTION, PROBABILITY FROM credit_scoring_100k_apply_data_v_rf WHERE PROBABILITY IN  (SELECT MAX(PROBABILITY)  FROM credit_scoring_100k_apply_data_v_rf GROUP BY CUSTOMER_ID) AND PREDICTION = ${PREDICTION='High', 'High'|'Medium'|'Low'} ORDER BY PROBABILITY DESC;

%script

-- Show the Predicted High Value Customers.

BEGIN EXECUTE IMMEDIATE 'DROP VIEW high_ltv_predicted_v';
EXCEPTION WHEN OTHERS THEN NULL; 
END;
/

CREATE VIEW high_ltv_predicted_v
AS 
SELECT CUSTOMER_ID, PREDICTION, PROBABILITY FROM credit_scoring_100k_apply_data_v_rf WHERE PROBABILITY IN  (SELECT MAX(PROBABILITY) FROM credit_scoring_100k_apply_data_v_rf GROUP BY CUSTOMER_ID) AND PREDICTION = 'High';

%sql

-- Show the Predicted High Valued Customers

SELECT CUSTOMER_ID, PROBABILITY FROM HIGH_LTV_PREDICTED_V;

%sql

-- Show the count of Predicted High Valued Customers

SELECT COUNT(*) FROM HIGH_LTV_PREDICTED_V;
